  'passkey.unavailable': 'इस सर्वर पर पासकी उपलब्ध नहीं हैं।',
  'passkey.admin_no_app_url': 'पासकी के लिए इस सर्वर का एक स्थायी सार्वजनिक पता चाहिए, और कोई सेट नहीं है। APP_URL को उस पते पर सेट करें जिसे लोग इस्तेमाल करते हैं (जैसे https://signage.example.com) और रीस्टार्ट करें। तब तक पासकी बंद रहेंगी, ताकि वे किसी अनुरोध के बताए किसी भी पते से न जुड़ें।',
  'passkey.admin_insecure': 'पासकी के लिए HTTPS चाहिए। APP_URL सादा http इस्तेमाल करता है, जिसकी ब्राउज़र सिर्फ़ localhost के लिए अनुमति देते हैं। इस सर्वर को HTTPS पर चलाएँ और APP_URL को https:// पते पर सेट करें।',
  'passkey.admin_ip': 'पासकी को IP पते से नहीं जोड़ा जा सकता। इस सर्वर को एक होस्ट नाम दें (भले ही लोकल हो) और APP_URL उस पर सेट करें।',
  'passkey.admin_bad_app_url': 'APP_URL मान्य पता नहीं है, इसलिए पासकी बंद हैं। APP_URL ठीक करें और रीस्टार्ट करें।',
