  'migrate.how.xibo': 'Xibo में Administration, फिर Applications खोलें, और "Client Credentials" पर टिक करके एक Application जोड़ें। उसका Client ID और Client Secret कॉपी करें। अपना CMS पता (जहाँ आप साइन इन करते हैं) डालें, जैसे https://cms.example.com।',
  'migrate.how.yodeck': 'Yodeck में Account Settings, Advanced Settings, API Tokens खोलें और एक टोकन बनाएँ (Premium या Enterprise प्लान)। इसे label:token के रूप में पेस्ट करें। Yodeck अपने API से मूल अपलोड की गई इमेज और दस्तावेज़ नहीं देता: उनकी सूची दिखाई जाती है ताकि आप उन्हें zip इंपोर्ट से जोड़ सकें। वीडियो उसी वर्ज़न में आते हैं जो Yodeck चलाता है।',
  'migrate.how.optisigns': 'OptiSigns का API है, लेकिन उसमें आपकी फ़ाइलें डाउनलोड करने का कोई तरीका नहीं बताया गया है, इसलिए प्लेलिस्ट खाली आएगी। OptiSigns से अपनी फ़ाइलें डाउनलोड करें और zip इंपोर्ट इस्तेमाल करें: हर प्लेलिस्ट के लिए एक फ़ोल्डर, या एक playlists.csv।',
  'migrate.how.screencloud': 'ScreenCloud Studio में Account Settings, फिर Developer टैब खोलें, और पढ़ने की अनुमति वाला एक टोकन बनाएँ। वहाँ दिखाया गया क्षेत्र (EU या US) चुनें। ScreenCloud समय के नियम अलग-अलग चैनल आइटम पर रखता है; उनकी सूची दिखाई जाती है, वे इंपोर्ट नहीं होते।',
  'migrate.how.anthias': 'अपने Anthias डिवाइस का पता डालें, जैसे http://192.168.1.20। अगर आपने ऑथेंटिकेशन चालू किया है, तो उसका यूज़रनेम और पासवर्ड डालें। हर डिवाइस एक प्लेलिस्ट वाली एक स्क्रीन के रूप में इंपोर्ट होता है।',
